\begin{proposition}[A weighted count of every full support]
\label{p1:uniform:full-support}
For fixed \(s\ge2\), \(u>0\), and \(\varepsilon>0\),
\[
 \sum_{r=s}^{|G|}\frac{u^r}{r!}
     \sum_{\boldsymbol x\in\mathcal H_{r,N}}p^r
       \ll_{s,u,C,\varepsilon}N^{-2s/(2s+1)+\varepsilon}.
\]
\end{proposition}

\begin{lemma}[The fourth factorial cumulant]
\label{p13:lower:quartic}
For every fixed critical band and every $\varepsilon>0$,
\begin{equation}
 \kappa_4=24K_4+O_{C,\varepsilon}(N^{-5/3+\varepsilon}),\qquad
 K_4=K_4^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}).
 \label{p13:lower:quartic-identities}
\end{equation}
Consequently
\begin{equation}
 \kappa_4+3\alpha^2
 =3\alpha^2+24K_4^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}).
 \label{p13:lower:positive-quartic}
\end{equation}
\end{lemma}
